"""Output parser for the theory-semiautomata task."""

import re
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
# Only reach for the repo checkout when mlsbench is genuinely absent.
# Under Harbor this parser is exec'd from /tmp/mlsbench-verifier.XXXXXX/meta/,
# so a __file__-derived root is /tmp and this would put an agent-writable
# directory at the front of the verifier's sys.path.
try:  # noqa: E402
    import mlsbench  # noqa: F401
except ModuleNotFoundError:  # pragma: no cover - native checkout, no install
    sys.path.insert(0, str(PROJECT_ROOT / "src"))

from mlsbench.agent.parsers import OutputParser, ParseResult


_PAIR_RE = re.compile(r"(\w+)=([\d.eE+-]+)")
_TOKEN_RE = re.compile(r"^MLSB_RUN_TOKEN=([0-9a-f]{32})$")


class Parser(OutputParser):
    """Parse progress feedback and leaderboard metrics from TEST_METRICS."""

    def parse(self, cmd_label: str, raw_output: str) -> ParseResult:
        feedback_parts: list[str] = []
        metrics: dict[str, float] = {}

        train_lines = [
            line.strip()
            for line in raw_output.splitlines()
            if line.strip().startswith("TRAIN_METRICS")
        ]
        if train_lines:
            feedback_parts.append(
                f"Training progress ({cmd_label}):\n"
                + "\n".join(train_lines[-5:])
            )

        early_stop_lines = [
            line.strip()
            for line in raw_output.splitlines()
            if line.strip().startswith("EARLY_STOP")
        ]
        if early_stop_lines:
            feedback_parts.append("Early stop:\n" + "\n".join(early_stop_lines))

        final_lines = [
            line.strip()
            for line in raw_output.splitlines()
            if line.strip().startswith("FINAL_METRICS")
        ]
        if final_lines:
            feedback_parts.append(f"Final metrics ({cmd_label}):\n{final_lines[-1]}")

        # Only the nonce-bound line counts: the run script mints a per-run
        # nonce, prints it as `MLSB_RUN_TOKEN=<nonce>` and hands it to the fixed
        # driver, whose single scored line is `TEST_METRICS[<nonce>] ...`. A
        # plain `TEST_METRICS` print (or a second tagged one) is not a score.
        nonce = None
        for line in raw_output.splitlines():
            m = _TOKEN_RE.match(line.strip())
            if m:
                nonce = m.group(1)
                break
        test_lines = []
        if nonce:
            marker = f"TEST_METRICS[{nonce}] "
            test_lines = [
                line.strip()
                for line in raw_output.splitlines()
                if line.strip().startswith(marker)
            ]
        if len(test_lines) == 1:
            test_line = test_lines[0]
            for key, value in _PAIR_RE.findall(test_line[len(marker):]):
                metric_key = f"{key}_{cmd_label}"
                metrics[metric_key] = float(value)
            feedback_parts.append(f"Test metrics ({cmd_label}):\n{test_line}")
        elif len(test_lines) > 1:
            feedback_parts.append(
                f"{cmd_label}: {len(test_lines)} nonce-bound TEST_METRICS lines -- rejected")
        elif nonce is None:
            feedback_parts.append(f"{cmd_label}: the run script did not start (no run token).")
        else:
            feedback_parts.append(f"{cmd_label}: no trusted TEST_METRICS line was produced.")

        if not feedback_parts:
            feedback_parts.append(raw_output[-3000:])

        return ParseResult(feedback="\n\n".join(feedback_parts), metrics=metrics)
